text:
{{
  (() => {
    const placa = String(inpCpPlaca.text || "").trim();
    const vehiculo = qCpBuscarVehiculoPorPlaca.data?.[0];

    if (!placa) return "";

    if (!vehiculo?.vehiculo_id) {
      return "Complete los datos para registrar el vehículo en el directorio.";
    }

    const fecha = vehiculo.soat_vencimiento
      ? new Date(
          `${String(vehiculo.soat_vencimiento).substring(0, 10)}T00:00:00`
        ).toLocaleDateString("es-CO")
      : "Sin registrar";

    const dias = Number(vehiculo.dias_vigencia_soat);

    const vigencia = Number.isFinite(dias)
      ? dias < 0
        ? `Vencido hace ${Math.abs(dias)} ${
            Math.abs(dias) === 1 ? "día" : "días"
          }`
        : dias === 0
          ? "Vence hoy"
          : `${dias} ${dias === 1 ? "día vigente" : "días vigentes"}`
      : "Vigencia no determinada";

    const capacidad = Number(vehiculo.capacidad_carga_kg);

    const capacidadTexto = Number.isFinite(capacidad)
      ? `${capacidad.toLocaleString("es-CO")} kg`
      : "Sin registrar";

    const alcance =
      vehiculo.habilitado_internacional === true
        ? "Nacional e internacional"
        : vehiculo.habilitado_nacional === true
          ? "Nacional"
          : "No definido";

    return [
      `SOAT: ${vehiculo.soat_no || "Sin registrar"} · Vencimiento: ${fecha}`,
      `${vigencia} · Capacidad: ${capacidadTexto}`,
      `Tipo: ${vehiculo.tipo_vehiculo || "Sin definir"} · Alcance: ${alcance}`
    ].join("\n");
  })()
}}
